/**
 * @summary Admin - Revenue chart data
 */
export const getGetRevenueChartUrl = (params?: GetRevenueChartParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/revenue-chart?${stringifiedParams}`
    : `/api/admin/revenue-chart`;
};

export const getRevenueChart = async (
  params?: GetRevenueChartParams,
  options?: RequestInit,
): Promise<ChartDataPoint[]> => {
  return customFetch<ChartDataPoint[]>(getGetRevenueChartUrl(params), {
    ...options,
    method: "GET",
  });
};

